using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public class ChatEvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static ReportingConfiguration? _reportingConfiguration;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _reportingConfiguration = CreateReportingConfiguration();
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        if (_appHost is not null)
        {
            var app = await _appHost.BuildAsync();
            await app.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task Chat_Responds_Relevantly()
    {
        await using var app = await _appHost.BuildAsync();
        await app.StartAsync();

        var chatClient = app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        var responseText = response.Text ?? string.Empty;

        Assert.IsFalse(string.IsNullOrWhiteSpace(responseText), "Chat response should not be empty.");

        await using var scenario = await CreateScenarioRunAsync(nameof(Chat_Responds_Relevantly));
        var evaluators = new IEvaluator[] { new RelevanceTruthAndCompletenessEvaluator() };
        await scenario.EvaluateAsync(messages, response, evaluators);
    }

    [TestMethod]
    public async Task Chat_Responds_Coherently()
    {
        await using var app = await _appHost.BuildAsync();
        await app.StartAsync();

        var chatClient = app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain how photosynthesis works in three sentences.")
        };

        var response = await chatClient.GetResponseAsync(messages);
        var responseText = response.Text ?? string.Empty;

        Assert.IsFalse(string.IsNullOrWhiteSpace(responseText), "Chat response should not be empty.");

        await using var scenario = await CreateScenarioRunAsync(nameof(Chat_Responds_Coherently));
        var evaluators = new IEvaluator[] { new CoherenceEvaluator() };
        await scenario.EvaluateAsync(messages, response, evaluators);
    }

    [TestMethod]
    public async Task Chat_Responds_Fluently()
    {
        await using var app = await _appHost.BuildAsync();
        await app.StartAsync();

        var chatClient = app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Write a brief summary of the benefits of exercise.")
        };

        var response = await chatClient.GetResponseAsync(messages);
        var responseText = response.Text ?? string.Empty;

        Assert.IsFalse(string.IsNullOrWhiteSpace(responseText), "Chat response should not be empty.");

        await using var scenario = await CreateScenarioRunAsync(nameof(Chat_Responds_Fluently));
        var evaluators = new IEvaluator[] { new FluencyEvaluator() };
        await scenario.EvaluateAsync(messages, response, evaluators);
    }

    [TestMethod]
    public async Task Chat_MultiTurn_Maintains_Context()
    {
        await using var app = await _appHost.BuildAsync();
        await app.StartAsync();

        var chatClient = app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "My name is Alice."),
        };

        var firstResponse = await chatClient.GetResponseAsync(messages);
        messages.AddRange(firstResponse.Messages);
        messages.Add(new ChatMessage(ChatRole.User, "What is my name?"));

        var response = await chatClient.GetResponseAsync(messages);
        var responseText = response.Text ?? string.Empty;

        Assert.IsFalse(string.IsNullOrWhiteSpace(responseText), "Chat response should not be empty.");
        Assert.IsTrue(
            responseText.Contains("Alice", StringComparison.OrdinalIgnoreCase),
            "Chat should maintain context across turns.");

        await using var scenario = await CreateScenarioRunAsync(nameof(Chat_MultiTurn_Maintains_Context));
        var evaluators = new IEvaluator[] { new RelevanceTruthAndCompletenessEvaluator() };
        await scenario.EvaluateAsync(messages, response, evaluators);
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var storagePath = Path.Combine(Path.GetTempPath(), "MyApp.Evaluation", "reports");
        Directory.CreateDirectory(storagePath);

        return DiskBasedReportingConfiguration.Create(storageDirectory: storagePath);
    }

    private static async Task<ScenarioRun> CreateScenarioRunAsync(string scenarioName)
    {
        return await _reportingConfiguration!.CreateScenarioRunAsync(scenarioName);
    }
}

