 using Aspire.Hosting;
 using Aspire.Hosting.Testing;
 using Microsoft.Extensions.AI;
 using Microsoft.Extensions.AI.Evaluation;
 using Microsoft.Extensions.AI.Evaluation.Quality;
 using Microsoft.Extensions.AI.Evaluation.Reporting;
 using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
 using Microsoft.Extensions.DependencyInjection;

 namespace MyApp.Evaluation;

 [TestClass]
 public class ChatEvaluationTests
 {
     private static DistributedApplication _app = null!;
     private static IChatClient _chatClient = null!;
     private static ReportingConfiguration _reportingConfiguration = null!;

     [ClassInitialize]
     public static async Task ClassInitialize(TestContext context)
     {
         var appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
         _app = await appHost.BuildAsync();
         await _app.StartAsync();

         _chatClient = _app.Services.GetRequiredService<IChatClient>();

         var storagePath = Path.Combine(Path.GetTempPath(), "MyApp.Evaluation", "reports");
         Directory.CreateDirectory(storagePath);

         _reportingConfiguration = DiskBasedReportingConfiguration.Create(
             storageRootPath: storagePath,
             evaluators:
             [
                 new CoherenceEvaluator(),
                 new FluencyEvaluator(),
                 new RelevanceTruthAndCompletenessEvaluator()
             ],
             chatConfiguration: new ChatConfiguration(_chatClient));
     }

     [ClassCleanup]
     public static async Task ClassCleanup()
     {
         if (_app is not null)
         {
             await _app.StopAsync();
             await _app.DisposeAsync();
         }
     }

     [TestMethod]
     public async Task Chat_Responds_Relevantly()
     {
         var messages = new List<ChatMessage>
         {
             new(ChatRole.User, "What is the capital of France?")
         };

         var response = await _chatClient.GetResponseAsync(messages);

         Assert.IsFalse(
             string.IsNullOrWhiteSpace(response.Text),
             "Chat response should not be empty.");

         await using var scenario = await _reportingConfiguration.CreateScenarioRunAsync(
             nameof(Chat_Responds_Relevantly));
         await scenario.EvaluateAsync(messages, response);
     }

     [TestMethod]
     public async Task Chat_Responds_Coherently()
     {
         var messages = new List<ChatMessage>
         {
             new(ChatRole.User, "Explain how photosynthesis works in three sentences.")
         };

         var response = await _chatClient.GetResponseAsync(messages);

         Assert.IsFalse(
             string.IsNullOrWhiteSpace(response.Text),
             "Chat response should not be empty.");

         await using var scenario = await _reportingConfiguration.CreateScenarioRunAsync(
             nameof(Chat_Responds_Coherently));
         await scenario.EvaluateAsync(messages, response);
     }

     [TestMethod]
     public async Task Chat_Responds_Fluently()
     {
         var messages = new List<ChatMessage>
         {
             new(ChatRole.User, "Write a brief summary of the benefits of exercise.")
         };

         var response = await _chatClient.GetResponseAsync(messages);

         Assert.IsFalse(
             string.IsNullOrWhiteSpace(response.Text),
             "Chat response should not be empty.");

         await using var scenario = await _reportingConfiguration.CreateScenarioRunAsync(
             nameof(Chat_Responds_Fluently));
         await scenario.EvaluateAsync(messages, response);
     }

     [TestMethod]
     public async Task Chat_MultiTurn_Maintains_Context()
     {
         var messages = new List<ChatMessage>
         {
             new(ChatRole.User, "My name is Alice.")
         };

         var firstResponse = await _chatClient.GetResponseAsync(messages);
         messages.AddRange(firstResponse.Messages);
         messages.Add(new ChatMessage(ChatRole.User, "What is my name?"));

         var response = await _chatClient.GetResponseAsync(messages);

         Assert.IsFalse(
             string.IsNullOrWhiteSpace(response.Text),
             "Chat response should not be empty.");
         Assert.IsTrue(
             response.Text!.Contains("Alice", StringComparison.OrdinalIgnoreCase),
             "Chat should maintain context across turns.");

         await using var scenario = await _reportingConfiguration.CreateScenarioRunAsync(
             nameof(Chat_MultiTurn_Maintains_Context));
         await scenario.EvaluateAsync(messages, response);
     }
 }

